class Solution {
  private int[] parent, parity;

  private int find(int x) {
    if (parent[x] == x) return x;
    int root = find(parent[x]);
    parity[x] ^= parity[parent[x]];
    parent[x] = root;
    return root;
  }

  public int maxPartitionFactor(int[][] points) {
    int n = points.length;
    if (n == 2) return 0;
    int m = n * (n - 1) / 2;
    long[] edges = new long[m];
    int idx = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        long d =
            Math.abs((long) points[i][0] - points[j][0])
                + Math.abs((long) points[i][1] - points[j][1]);
        edges[idx++] = (d << 20) | (i << 10) | j;
      }
    }
    java.util.Arrays.sort(edges);
    parent = new int[n];
    parity = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    for (long e : edges) {
      int a = (int) (e >> 10 & 1023), b = (int) (e & 1023);
      int ra = find(a), rb = find(b);
      if (ra == rb) {
        if (parity[a] == parity[b]) return (int) (e >> 20);
      } else {
        parent[ra] = rb;
        parity[ra] = parity[a] ^ parity[b] ^ 1;
      }
    }
    return 0;
  }
}
